contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint v1, uint v2) public payable {
        require(v1 > 0 && v2 > 0);
        require(address(this).balance >= v1 + v2);
        c.addToBalance{value: v1}();
        c.withdrawBalance();
        assert(c.getBalance(address(this)) == 0);
        // second, distinct usage: deposit and withdraw again in the same tx
        c.addToBalance{value: v2}();
        assert(c.getBalance(address(this)) == v2);
        assert(address(c).balance == v2);
        c.withdrawBalance();
        assert(c.getBalance(address(this)) == 0);
        assert(address(c).balance == 0);
    }
    receive() external payable {}
}

